    "layer": 1,
    "type": "instruction"
  },
  "meta": {
    "description": "Правила и форматы удаления файлов из репозитория. Удаление необратимо.",
    "status": "active",
    "priority": "critical",
    "tags": ["delete", "instructions", "honeycomb", "workflow"]
