    "title": "Удаление файла через delete_file: true",
    "rule": "delete_file: true не требует content, changes или replacements — только путь к файлу.",
    "via_target_module": {
      "description": "Удаление через target_module — путь БЕЗ .json",
      "example": {
        "target_module": "honeycombs/seeds/core/old_idea",
        "delete_file": true
      }
    },
    "via_file_path": {
      "description": "Удаление через file_path — путь С расширением",
      "example": {
        "file_path": "honeycombs/seeds/core/old_idea.json",
        "delete_file": true
      }
    },
    "multi_delete": {
      "description": "Удаление нескольких файлов одним патчем",
      "example": {
        "patches": [
          {"target_module": "honeycombs/seeds/core/old_idea_1", "delete_file": true},
